    words, tokenize = 'ascii', content = '', contentless_delete = 1, detail = none
)

triggers.media_asset_copy_deleted:
CREATE TRIGGER media_asset_copy_deleted AFTER DELETE ON media_asset
WHEN OLD.copy_key IS NOT NULL
BEGIN
DELETE FROM copy_key_touched;
INSERT INTO copy_key_touched (key) VALUES (OLD.copy_key);
UPDATE media_asset SET
    shown_copy_root_id = (
        SELECT copy.library_root_id FROM media_asset AS copy INDEXED BY idx_media_asset_copy_key
        WHERE copy.copy_key = media_asset.copy_key AND copy.pending_trash_batch_unix_ms IS NULL AND copy.awaiting_presence = 0 AND copy.hidden_by_source = 0
          AND (((SELECT kind FROM library_root WHERE id = copy.library_root_id) = 'immichAccount'), copy.library_root_id, copy.relative_path) < (((SELECT kind FROM library_root WHERE id = media_asset.library_root_id) = 'immichAccount'), media_asset.library_root_id, media_asset.relative_path)
        ORDER BY ((SELECT kind FROM library_root WHERE id = copy.library_root_id) = 'immichAccount'), copy.library_root_id, copy.relative_path
        LIMIT 1
    ),
    has_copies = EXISTS (
        SELECT 1 FROM media_asset AS copy INDEXED BY idx_media_asset_copy_key
        WHERE copy.copy_key = media_asset.copy_key AND copy.pending_trash_batch_unix_ms IS NULL AND copy.awaiting_presence = 0 AND copy.hidden_by_source = 0 AND copy.rowid <> media_asset.rowid
    )
WHERE copy_key IN (SELECT key FROM copy_key_touched);
DELETE FROM copy_key_touched;
END
